function arcPath(r, a0, a1) {
  var p0 = polarPoint(r, a0);
  var p1 = polarPoint(r, a1);
  var da = a1 - a0;
  var large = Math.abs(da) > 180 ? 1 : 0;
  var sweep = da >= 0 ? 1 : 0;
  return 'M ' + p0.x + ' ' + p0.y + ' A ' + r + ' ' + r + ' 0 ' + large + ' ' + sweep + ' ' + p1.x + ' ' + p1.y;
}

