    var right = state.n2 * Math.sin(degToRad(theta2));
    readout.innerHTML =
      'n₁ sin θ₁ = n₂ sin θ₂<br>' +
      'θ₁ = ' + fmt1(theta1) + '°; θ₂ = ' + fmt1(theta2) + '°<br>' +
      fmt2(left) + ' = ' + fmt2(right);
