  dragHandle.center(source.x, source.y);

  var sin2 = (state.n1 / state.n2) * Math.sin(t1);
  var isTIR = state.n1 > state.n2 && sin2 > 1;
  var theta2 = isTIR ? NaN : radToDeg(Math.asin(clamp(sin2, -1, 1)));

  theta1Arc.attr({ d: arcPath(56, -90 - theta1, -90) });
