  placeText(theta1Label, pTheta1.x - 4, pTheta1.y + 10, 'θ₁');

  if (isTIR) {
    setVisible(refractedLine, false);
    setVisible(theta2Arc, false);
    setVisible(theta2Label, false);

    var reflectedEnd = {
      x: O.x + L2 * Math.sin(t1),
