    };
    reflectedLine.attr({ x1: O.x, y1: O.y, x2: reflectedEnd.x, y2: reflectedEnd.y });
    setVisible(reflectedLine, true);

    thetaRArc.attr({ d: arcPath(56, -90, -90 + theta1) });
