    var pThetaR = polarPoint(76, -90 + theta1 / 2);
    placeText(thetaRLabel, pThetaR.x + 8, pThetaR.y + 2, 'θᵣ');
    setVisible(thetaRLabel, true);

    placeText(tirLabel, 495, 178, 'total internal reflection');
    setVisible(tirLabel, true);
  } else {
    var t2 = degToRad(theta2);
    var refractedEnd = {
      x: O.x + L2 * Math.sin(t2),
      y: O.y + L2 * Math.cos(t2)
    };
    refractedLine.attr({ x1: O.x, y1: O.y, x2: refractedEnd.x, y2: refractedEnd.y });
    setVisible(refractedLine, true);
    setVisible(reflectedLine, false);
    setVisible(thetaRArc, false);
