    setVisible(thetaRLabel, false);
    setVisible(tirLabel, false);

    theta2Arc.attr({ d: arcPath(56, 90 - theta2, 90) });
    setVisible(theta2Arc, true);

    var pTheta2 = polarPoint(95, 90 - theta2 / 2);
    placeText(theta2Label, pTheta2.x + 18, pTheta2.y + 20, 'θ₂');
    setVisible(theta2Label, true);
  }

  var showCritical = (state.n1 > state.n2) && (currentStep === 2 || isTIR);
  if (showCritical) {
    var thetaC = radToDeg(Math.asin(clamp(state.n2 / state.n1, -1, 1)));
    criticalGroup.show();

    criticalArc.attr({ d: arcPath(104, -90 - thetaC, -90) });
    var critEnd = {
      x: O.x - 180 * Math.sin(degToRad(thetaC)),
      y: O.y - 180 * Math.cos(degToRad(thetaC))
    };
    criticalRay.attr({ x1: O.x, y1: O.y, x2: critEnd.x, y2: critEnd.y });

    var pc = polarPoint(123, -90 - thetaC / 2);
    placeText(criticalLabel, pc.x - 8, pc.y - 8, 'θc ≈ ' + fmt1(thetaC) + '°');
    setVisible(criticalLabel, true);
  } else {
    criticalGroup.hide();
    setVisible(criticalLabel, false);
  }

  var labelX = source.x + 50;
  var labelY = source.y + 14;
  placeText(rayDirLabel, labelX, labelY, 'ray direction');
  rayDirLabel.attr('transform', 'rotate(56 ' + labelX + ' ' + labelY + ')');

  updateReadout(theta1, theta2, isTIR, sin2);
}

function svgPoint(evt) {
  var pt = draw.node.createSVGPoint();
  pt.x = evt.clientX;
  pt.y = evt.clientY;
  return pt.matrixTransform(draw.node.getScreenCTM().inverse());
}

var dragging = false;

function beginDrag(evt) {
  dragging = true;
  if (evt && evt.preventDefault) evt.preventDefault();
  updateDrag(evt);
}

function updateDrag(evt) {
  if (!dragging || !evt) return;
  if (evt.preventDefault) evt.preventDefault();

  var p = svgPoint(evt);
  var dx = p.x - O.x;
  var dy = p.y - O.y;

  if (dy > -3) dy = -3;
  var leftward = Math.max(0, -dx);
  var upward = Math.max(1, -dy);
  state.theta1 = clamp(radToDeg(Math.atan2(leftward, upward)), 3, 82);

  render();
}

function endDrag() {
  dragging = false;
}

incidentLine.on('pointerdown', beginDrag);
hitLine.on('pointerdown', beginDrag);
dragHandle.on('pointerdown', beginDrag);
hitLine.css('touch-action', 'none');
incidentLine.css('touch-action', 'none');
dragHandle.css('touch-action', 'none');

window.addEventListener('pointermove', updateDrag, { passive: false });
window.addEventListener('pointerup', endDrag);
window.addEventListener('pointercancel', endDrag);

function update_refractiveIndexN1(v) {
  state.n1 = v;
  var out = document.getElementById('refractiveIndexN1Val');
  if (out) out.value = v.toFixed(2);
  render();
}

function update_refractiveIndexN2(v) {
  state.n2 = v;
  var out = document.getElementById('refractiveIndexN2Val');
  if (out) out.value = v.toFixed(2);
  render();
}

function setSlider(id, v) {
  var input = document.getElementById(id + 'Input');
  var out = document.getElementById(id + 'Val');
  if (input) input.value = v;
  if (out) out.value = (+v).toFixed(2);
}

function applyStep(i) {
  currentStep = clamp(i, 0, demoSteps.length - 1);
  var s = demoSteps[currentStep];

  state.theta1 = s.theta;
  setSlider('refractiveIndexN1', s.state.refractiveIndexN1);
  setSlider('refractiveIndexN2', s.state.refractiveIndexN2);

  state.n1 = s.state.refractiveIndexN1;
  state.n2 = s.state.refractiveIndexN2;

  var narr = document.getElementById('demoNarration');
  var lab = document.getElementById('stepLabel');
  if (narr) narr.textContent = s.narration;
  if (lab) lab.textContent = (currentStep + 1) + '/' + demoSteps.length + ' ' + s.title;

  render();
}

function nextStep() { applyStep(currentStep + 1); }
function prevStep() { applyStep(currentStep - 1); }

window.update_refractiveIndexN1 = update_refractiveIndexN1;
window.update_refractiveIndexN2 = update_refractiveIndexN2;
window.nextStep = nextStep;
window.prevStep = prevStep;

setVisible(reflectedLine, false);
setVisible(thetaRArc, false);
setVisible(thetaRLabel, false);
setVisible(tirLabel, false);
criticalGroup.hide();
setVisible(criticalLabel, false);

applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

